<template><section class="handoff-panel"><h2>Create delivery work</h2><p class="text-muted">Link a sales or CRM record to one delivery project. Repeating the handoff opens the existing project.</p><p v-if="error" role="alert">{{ error }}</p><form @submit.prevent="create"><label>Source type<select v-model="sourceType" class="field"><option>Sales Order</option><option>CRM Deal</option><option>Opportunity</option></select></label><label>Source record ID<input v-model="sourceName" class="field" required /></label><label>Project name<input v-model="title" class="field" required /></label><label>Project template (optional)<input v-model="template" class="field" placeholder="Existing template project ID" /></label><button class="btn-primary" :disabled="busy">{{ busy ? 'Creating…' : 'Create delivery project' }}</button></form><p v-if="result" role="status">{{ result.created ? 'Delivery project created.' : 'This source already has a delivery project.' }} <RouterLink :to="{path:'/board',query:{project:result.project}}">Open project</RouterLink></p></section></template>
<script setup>
import {ref} from 'vue'
import {call} from 'frappe-ui'
const emit=defineEmits(['created'])
const sourceType=ref('Sales Order'),sourceName=ref(''),title=ref(''),template=ref(''),busy=ref(false),error=ref(''),result=ref(null)
async function create(){busy.value=true;error.value='';result.value=null;try{result.value=await call('pulse.api.handoffs.create',{source_doctype:sourceType.value,source_name:sourceName.value,project_name:title.value,template:template.value||null});emit('created',result.value)}catch(e){error.value=e.messages?.join(' ')||'Unable to create delivery work. Check the source and your permissions.'}finally{busy.value=false}}
</script>
<style scoped>.handoff-panel{padding:20px;border:1px solid var(--border-color,#e6e8ec);border-radius:8px;margin:16px 0}.handoff-panel h2{font-weight:600;font-size:16px}.handoff-panel p{font-size:13px;margin:8px 0}.handoff-panel form{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:16px}.handoff-panel label{display:grid;gap:6px;font-size:13px}.handoff-panel button{justify-self:start}@media(max-width:700px){.handoff-panel form{grid-template-columns:1fr}}</style>
